import json, re
path = "/private/tmp/claude-501/-Users-rina--claude/bcb2f2c2-3bd5-40de-a21c-025da566713f/scratchpad/batches/batch_0061.json"
data = json.load(open(path, encoding='utf-8'))

def looks_mojibake(s):
    if not s: return False
    # heuristic: many latin-1 supplement chars in a row, or high ratio of chars in 0x80-0xFF range mixed with normal ascii
    count = sum(1 for c in s if 0x80 <= ord(c) <= 0xFF)
    return count > len(s) * 0.15

def try_fix(s):
    if not s:
        return s, "empty"
    # Attempt B: latin1 -> cp932
    try:
        b = s.encode('latin1')
        fixed = b.decode('cp932')
        # sanity: should contain hiragana/katakana/kanji
        if re.search(r'[぀-ヿ一-鿿]', fixed):
            return fixed, "cp932"
    except Exception:
        pass
    # Attempt A: latin1(replace) -> utf-8(replace)
    try:
        b = s.encode('latin1', errors='replace')
        fixed = b.decode('utf-8', errors='replace')
        if re.search(r'[぀-ヿ一-鿿]', fixed):
            return fixed, "utf8-double"
    except Exception:
        pass
    return s, "unfixed"

flagged = []
for item in data:
    for field in ['title','desc','body']:
        v = item.get(field,'')
        if looks_mojibake(v):
            fixed, method = try_fix(v)
            flagged.append((item['idx'], item['name'], field, method))

for f in flagged:
    print(f)
